INSERT INTO glosario (term, definition, category, aliases, source) VALUES
  ('acícula', 'Hoja larga, fina y rígida con forma de aguja, típica de los pinos.', 'botánica', '["acículas"]', 'NaturDex (divulgacion)'),
  ('acuminado', 'Que se estrecha en el extremo formando una punta alargada y fina.', 'botánica', '["acuminada","acuminados","acuminadas"]', 'NaturDex (divulgacion)'),
  ('afieltrado', 'Cubierto de pelos entrelazados muy densos, que le dan tacto y aspecto de fieltro.', 'botánica', '["afieltrada","afieltrados","afieltradas","fieltro"]', 'NaturDex (divulgacion)'),
  ('agalla', 'Bulto que forma la planta como reacción a la picadura de un insecto, que se cría dentro.', 'botánica', '["agallas"]', 'NaturDex (divulgacion)'),
